css:
/* DEWGLASS (aero) — Frutiger Aero starter theme, theme author guide v1.5.
   ONE IDEA: everything is a dewdrop of gel glass.
   - Every surface is a droplet: fat rounded glass with a hard-edged GEL CAP (a bright specular
     band laid over its top) and a soft caustic glow pooled at its foot.
   - Messages are teardrop speech droplets: three round corners, one pinched tip that points at
     the speaker, who is a glass MARBLE (avatar sphere with a specular crescent).
   - The message box is a long gel capsule docked to a round glass ORB (send).
   - Home widgets are desktop "gadgets": chrome-rimmed glass tiles with a gel cap title band.
   - The top bar is a glass taskbar with an aurora swoosh; tabs are gel pills.
   - Sidebars are frosted slabs where every row is a gel pill; the open chat is a lit aqua pill.
   - Dialogs and panels are big droplets with an aurora ribbon across the cap.
   - Soap bubbles rise in the side gutters (never over the reading column). */

:root{
  --mari-tokens-version:1;
  --dg-font:"Dewglass Sans","Source Sans 3","Segoe UI","Myriad Pro",system-ui,sans-serif;
  --dg-round:"Dewglass Round","Varela Round","Dewglass Sans",system-ui,sans-serif;
  --mari-font-ui:var(--dg-font);
  --mari-font-heading:var(--dg-round);
  --mari-font-chat:var(--dg-font);
  --ov-serif:var(--dg-round);
  --radius:1.1rem;
  --mari-chat-font-size:17px;
  --mari-chat-line-height:1.6;
  --mari-chat-column:43rem;
  --mari-paragraph-gap:0.8em;
  --mari-dialogue-weight:500;
  --mari-text-outline:0;
  --mari-min-ui-text:12px;
  --mari-toast-font-size:0.95rem;
  --mari-selected-tint:var(--primary);
  --marinara-theme-accent-pulse:none;
  --mari-home-art:none;
  --mari-msg-head-rule:none;
  --mari-phone-avatar:hidden;
  --mari-chat-row-art-opacity:0;
  --mari-composer-placeholder:"Say something...";
  --mari-top-bar-plate-radius:999px;
  --mari-home-widget-radius:26px;
  --mari-home-widget-border-width:1px;
  --mari-home-widget-font:var(--dg-font);
  --mari-home-widget-title-font:var(--dg-round);
  --mari-home-widget-title-size:1.45rem;
  --mari-home-widget-eyebrow-size:0.72rem;
  --mari-home-widget-text-size:0.95rem;
  --mari-home-widget-action-size:0.92rem;
  --mari-app-backdrop-position:center bottom;

  /* shared geometry */
  --dg-drop:26px;           /* round corner of a droplet */
  --dg-tip:3px;             /* the pinched tip */
  --dg-cap:2.9rem;         /* height of the gel cap on messages */
  --dg-ease:cubic-bezier(.2,.8,.2,1);

  /* the bubbles in the gutters: behind the cards, masked away from the column */
  --mari-ambient:
    url("theme:gutter-bubbles.webp") 3% 0 / 180px auto repeat-y,
    url("theme:gutter-bubbles.webp") 97% 700px / 150px auto repeat-y;
  --mari-ambient-placement:behind-cards;
  --mari-ambient-mask:var(--mari-gutter-mask);
  --mari-gutter-clear:35rem;
  --mari-ambient-opacity:0.7;
  --mari-ambient-animation:dg-rise 60s linear infinite;
}
@keyframes dg-rise{
  from{background-position:3% 0,97% 700px}
  to{background-position:3% -1600px,97% -633px}
}

/* ── DAY: bright sky, white glass, navy ink ───────────────────────── */
:root[data-theme="light"]{
  --dg-ink:#0a2f4a; --dg-mute:#2f5670; --dg-faint:#4a6c82;
  --dg-aqua:#0672b3; --dg-aqua-hi:#19b5e8; --dg-lime:#2f8a12; --dg-lime-hi:#7ed957;
  --dg-on-aqua:#ffffff;
  --dg-speech:#075a8e;
  --dg-gel-a:#d8f6ff; --dg-gel-b:#6fd2f2; --dg-on-gel:#03263b;
  --dg-glass:rgba(214,239,251,.86);
  --dg-glass-solid:#f2fbff;
  --dg-glass-deep:rgba(232,247,255,.9);
  --dg-glass-user:rgba(220,247,232,.88);
  --dg-rim:rgba(255,255,255,.95);
  --dg-rim-out:rgba(10,90,140,.28);
  --dg-shadow:0 10px 28px -10px rgba(8,70,120,.45), 0 2px 6px rgba(8,70,120,.12);
  --dg-cap-hi:rgba(255,255,255,1); --dg-cap-mid:rgba(255,255,255,.82); --dg-cap-lo:rgba(255,255,255,.5);
  --dg-caustic:rgba(120,230,255,.28);
  --dg-sidebar:rgba(236,249,255,.80);
  --mari-app-backdrop:url("theme:backdrop-day.webp");
  --mari-stage-empty-bg:url("theme:game-stage.webp") center / cover no-repeat;
  --mari-art-lightness-1:72%; --mari-art-lightness-2:58%;
  --mari-art-saturation-1:70%; --mari-art-saturation-2:65%;
}
/* ── NIGHT: deep lagoon, smoked aqua glass, ice ink ───────────────── */
:root,:root[data-theme="dark"]{
  --dg-ink:#e8f9ff; --dg-mute:#b3d6e6; --dg-faint:#93bccf;
  --dg-aqua:#3fd6f5; --dg-aqua-hi:#9cf0ff; --dg-lime:#7dff9a; --dg-lime-hi:#c6ffb0;
  --dg-on-aqua:#03263b;
  --dg-speech:#a6ecfa;
  --dg-gel-a:#9ff2ff; --dg-gel-b:#1fb3d8; --dg-on-gel:#02202f;
  --dg-glass:rgba(8,46,72,.6);
  --dg-glass-solid:#062437;
  --dg-glass-deep:rgba(6,34,56,.78);
  --dg-glass-user:rgba(8,64,62,.62);
  --dg-rim:rgba(190,246,255,.5);
  --dg-rim-out:rgba(0,0,0,.45);
  --dg-shadow:0 12px 30px -10px rgba(0,8,20,.8), 0 0 0 1px rgba(0,0,0,.2);
  --dg-cap-hi:rgba(210,252,255,.44); --dg-cap-mid:rgba(170,240,255,.16); --dg-cap-lo:rgba(170,240,255,.05);
  --dg-caustic:rgba(60,220,255,.16);
  --dg-sidebar:rgba(5,30,52,.62);
  --mari-app-backdrop:url("theme:backdrop-night.webp");
  --mari-stage-empty-bg:linear-gradient(rgba(2,20,40,.55),rgba(2,20,40,.55)), url("theme:game-stage.webp") center / cover no-repeat;
  --mari-art-lightness-1:30%; --mari-art-lightness-2:20%;
  --mari-art-saturation-1:70%; --mari-art-saturation-2:60%;
}

/* ── tokens shared by both schemes ────────────────────────────────── */
:root,:root[data-theme="dark"],:root[data-theme="light"]{
  /* the gel cap and the foot glow, reused on every droplet */
  --dg-gel:radial-gradient(farthest-side at 50% 0%,var(--dg-cap-hi) 0%,var(--dg-cap-mid) 50%,var(--dg-cap-lo) 82%,transparent 100%) 4px 2px / calc(100% - 8px) var(--dg-cap) no-repeat;
  --dg-gel-rim:inset 0 1px 0 rgba(255,255,255,.85), inset 0 0 0 1px rgba(255,255,255,.18), inset 0 -10px 18px -12px var(--dg-caustic);
  --dg-foot:radial-gradient(120% 60% at 50% 100%,var(--dg-caustic),transparent 70%) bottom / 100% 70% no-repeat;
  --dg-gel-pill:radial-gradient(farthest-side at 50% 0%,var(--dg-cap-hi) 0%,var(--dg-cap-mid) 60%,transparent 100%) 3px 1px / calc(100% - 6px) 55% no-repeat;
  --dg-aqua-gel:radial-gradient(farthest-side at 50% 0%,rgba(255,255,255,.75) 0%,rgba(255,255,255,.35) 60%,transparent 100%) 3px 1px / calc(100% - 6px) 55% no-repeat,
                linear-gradient(180deg,var(--dg-gel-a),var(--dg-gel-b));

  --background:var(--dg-glass-solid); --foreground:var(--dg-ink);
  --card:var(--dg-glass); --card-foreground:var(--dg-ink);
  --popover:var(--dg-glass-deep); --popover-foreground:var(--dg-ink);
  --primary:var(--dg-aqua); --primary-foreground:var(--dg-on-aqua);
  --secondary:color-mix(in srgb,var(--dg-aqua) 10%,var(--dg-glass-solid)); --secondary-foreground:var(--dg-ink);
  --muted:color-mix(in srgb,var(--dg-aqua) 8%,var(--dg-glass-solid)); --muted-foreground:var(--dg-mute);
  --accent:color-mix(in srgb,var(--dg-aqua) 14%,var(--dg-glass-solid)); --accent-foreground:var(--dg-ink);
  --destructive:#d6334a; --destructive-foreground:#fff;
  --border:color-mix(in srgb,var(--dg-aqua) 26%,transparent);
  --input:color-mix(in srgb,var(--dg-aqua) 30%,transparent);
  --ring:var(--dg-aqua);
  --sidebar:var(--dg-sidebar); --sidebar-foreground:var(--dg-ink);
  --sidebar-border:var(--dg-rim);
  --sidebar-accent:color-mix(in srgb,var(--dg-aqua) 14%,transparent); --sidebar-accent-foreground:var(--dg-ink);
  --ov-line:color-mix(in srgb,var(--dg-aqua) 22%,transparent);
  --ov-text:var(--dg-ink); --ov-muted:var(--dg-mute); --ov-dim:var(--dg-faint);
  --ov-accent:var(--dg-aqua);
  --ov-hover:color-mix(in srgb,var(--dg-aqua) 10%,transparent);
  --ov-active-bg:color-mix(in srgb,var(--dg-aqua) 16%,transparent);
  --ov-mode-conversation:var(--dg-aqua); --ov-mode-roleplay:var(--dg-lime); --ov-mode-game:#e08a00;
  --mari-mode-conversation:var(--dg-aqua); --mari-mode-roleplay:var(--dg-lime); --mari-mode-game:#d07a00;
  --mari-home-pink:#d0408a; --mari-home-violet:#6b55d6;
  --mari-status-online:#2fbf3a; --mari-status-idle:#e8a400; --mari-status-dnd:#e0344c; --mari-status-offline:var(--dg-faint);
  --mari-gauge-ok:#2fbf3a; --mari-gauge-warn:#e8a400; --mari-gauge-danger:#e0344c;
  --mari-game-combat:#e0344c; --mari-game-combat-text:#fff;
  --mari-scrim:color-mix(in srgb,var(--dg-glass-solid) 55%,transparent);
  --mari-user-avatar-placeholder:radial-gradient(circle at 35% 30%,#ffffff 0 12%,#9cf0ff 30%,#0a8fd6 75%,#064f80);
  --mari-dialogue-color:var(--dg-speech);
  --mari-message-time:var(--dg-faint);
  --mari-message-actions:var(--dg-mute);
  --mari-swipe-counter:var(--dg-mute);
  --mari-chrome-accent:var(--dg-aqua);
  --mari-chrome-muted:var(--dg-mute);
  --mari-chat-wash:none;
  --mari-chat-header-bg:none;
  --mari-page-veil:transparent;
  --mari-home-wash:transparent;
  --mari-home-widget-bg:var(--dg-gel), var(--dg-foot), var(--dg-glass);
  --mari-home-widget-border:var(--dg-rim);
  --mari-home-widget-title-color:var(--dg-ink);
  --mari-home-widget-muted:var(--dg-mute);
  --mari-home-widget-eyebrow-color:var(--dg-aqua);
  --mari-home-widget-glow:transparent;
  --mari-lore-constant:var(--dg-aqua); --mari-lore-selective:var(--dg-lime); --mari-lore-normal:var(--dg-faint);
  --mari-resource-accent:var(--dg-aqua);
  --mari-ctrlk-conversation:var(--dg-aqua); --mari-ctrlk-roleplay:var(--dg-lime); --mari-ctrlk-game:#d07a00;
  --mari-card-art-placeholder:radial-gradient(circle at 30% 25%,rgba(255,255,255,.7) 0 8%,transparent 30%),
                              linear-gradient(160deg,var(--dg-aqua-hi),var(--dg-aqua) 60%,var(--dg-lime));
  --mari-focus-ring-color:var(--dg-aqua);

  /* top bar: glass taskbar with an aurora swoosh */
  --mari-top-bar-bg:
    url("theme:aurora-strip.webp") right center / auto 100% no-repeat,
    radial-gradient(farthest-side at 50% 0%,var(--dg-cap-hi) 0%,var(--dg-cap-mid) 50%,transparent 100%) 0 0 / 100% 55% no-repeat,
    var(--dg-sidebar);
  --mari-top-bar-plate:color-mix(in srgb,var(--dg-glass-solid) 70%,transparent);
  --mari-top-bar-plate-active:color-mix(in srgb,var(--dg-aqua) 26%,var(--dg-glass-solid));
}

/* ── Weather: bubbles and glints, not grey drizzle ──────────────── */
:root{
  --mari-weather-dust-image:url("theme:snow-dot.webp");
  --mari-weather-dust-size:0.5;
  --mari-weather-leaf-image:url("theme:leaf.webp");
  --mari-weather-leaf-size:1.1;
  --mari-weather-rain-length:1.5;
  --mari-weather-strength:1.3;
  --mari-weather-snow-image:url("theme:snow-soft.webp") url("theme:snow-dot.webp") url("theme:snow-soft.webp") url("theme:flake-2.webp");
  --mari-weather-fog-color:#dff6ff;
  --mari-weather-tint-strength:0.6;
  --mari-weather-lightning-color:#a8f6ff;
  --mari-weather-sun:none;
  --mari-weather-lightning-bolt:3;
  --mari-weather-aurora-color:#7dff9a;
}
:root[data-theme="light"]{
  --mari-weather-rain-color:#2d9fd8;
  --mari-weather-snow-size:0.6;
  --mari-weather-sun-color:#fff6c8;
}
:root[data-theme="dark"]{
  --mari-weather-rain-color:#8ff3ff;
  --mari-weather-snow-size:0.55;
  --mari-weather-star-color:#c9f6ff;
  --mari-weather-firefly-color:#9cff7a;
  --mari-weather-fog-color:#7fc9df;
  --mari-weather-moon-color:#e8fbff;
}
:root[data-mari-weather="clear"],:root[data-mari-weather="cloudy"]{ --mari-weather-amount:0.6; }
:root[data-mari-weather="fog"]{ --mari-weather-tint-strength:1; --mari-weather-strength:1.5; }
:root[data-theme="light"][data-mari-weather="rain"],
:root[data-theme="light"][data-mari-weather="storm"],
:root[data-theme="light"][data-mari-weather="fog"]{ --mari-app-backdrop:url("theme:backdrop-rain.webp"); }
:root[data-theme="light"][data-mari-weather="snow"],
:root[data-theme="light"][data-mari-weather="hail"]{ --mari-app-backdrop:url("theme:backdrop-snow.webp"); }
:root[data-theme="dark"][data-mari-weather="rain"],
:root[data-theme="dark"][data-mari-weather="storm"],
:root[data-theme="dark"][data-mari-weather="fog"]{ --mari-app-backdrop:url("theme:backdrop-rain-night.webp"); }
:root[data-theme="dark"][data-mari-weather="snow"],
:root[data-theme="dark"][data-mari-weather="hail"]{ --mari-app-backdrop:url("theme:backdrop-snow-night.webp"); }
:root[data-mari-weather]:not([data-mari-weather="clear"],[data-mari-weather="cloudy"]){ --mari-ambient:none; }

/* ═══ TOP BAR: glass taskbar; tabs are gel pills ═══════════════════ */
[data-component="TopBar"]{
  border-bottom:1px solid var(--dg-rim) !important;
  box-shadow:0 1px 0 var(--dg-rim-out), 0 6px 18px -8px rgba(8,70,120,.35);
}
[data-component="TopBar"] .ov-tab,
[data-component="TopBar"] .ov-text-btn{
  border-radius:999px;
  font-family:var(--dg-font);
  font-weight:600;
  color:var(--dg-ink);
}
[data-component="TopBar"] .ov-tab.is-on{
  background:var(--dg-aqua-gel) !important;
  color:var(--dg-on-gel) !important;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.55), 0 2px 6px -1px rgba(6,90,150,.5);
}
[data-component="TopBar"] .ov-tab.is-on *{ color:inherit; }
[data-component="TopBar"] .ov-tab.is-on .ov-tab__dot{ background:var(--dg-on-gel) !important; }
[data-component="TopBar"] .ov-icon-btn{ border-radius:999px; color:var(--dg-ink); }

/* ═══ SIDEBARS: frosted slabs, every row a gel pill ═════════════════ */
[data-component="ChatSidebar"],
[data-component="RightPanelDesktop"]{
  backdrop-filter:blur(18px) saturate(1.3);
  -webkit-backdrop-filter:blur(18px) saturate(1.3);
  box-shadow:inset -1px 0 0 var(--dg-rim);
}
[data-component="RightPanelDesktop"]{ box-shadow:inset 1px 0 0 var(--dg-rim); }
[data-chat-row]{
  border-radius:999px !important;
  margin-inline:6px;
  transition:background .2s var(--dg-ease);
}
[data-chat-row]:hover{ background:color-mix(in srgb,var(--dg-aqua) 10%,transparent); }
[data-chat-row][data-selected="true"]{
  background:var(--dg-gel-pill), color-mix(in srgb,var(--dg-aqua) 22%,var(--dg-glass-solid)) !important;
  box-shadow:inset 0 0 0 1px var(--dg-rim), 0 3px 10px -4px rgba(6,90,150,.45);
}
[data-chat-row][data-selected="true"]::before{ display:none; }

/* ═══ MESSAGES: teardrop droplets, gel cap, marble avatars ═════════ */
.mari-rp-bubble{
  border-radius:var(--dg-tip) var(--dg-drop) var(--dg-drop) var(--dg-drop) !important;
  background:var(--dg-gel), var(--dg-foot), var(--dg-glass) !important;
  border:1px solid var(--dg-rim) !important;
  box-shadow:var(--dg-shadow), var(--dg-gel-rim) !important;
  backdrop-filter:blur(14px) saturate(1.4);
  -webkit-backdrop-filter:blur(14px) saturate(1.4);
  color:var(--dg-ink);
}
.mari-rp-bubble--user,
[data-mari-part="message"][data-message-role="user"] .mari-rp-bubble{
  border-radius:var(--dg-drop) var(--dg-tip) var(--dg-drop) var(--dg-drop) !important;
  background:var(--dg-gel), var(--dg-foot), var(--dg-glass-user) !important;
}
[data-mari-part="message"] [data-mari-part="header"]{
  min-height:calc(var(--dg-cap) - 1.5rem);
}
[data-mari-part="message"] .mari-message-name{
  font-family:var(--dg-round);
  font-weight:400;
  font-size:1.02rem;
  letter-spacing:.01em;
  color:var(--dg-ink) !important;
}
[data-mari-part="message"] .mari-message-content{ color:var(--dg-ink); }
[data-mari-part="message"] em,[data-mari-part="message"] i{ color:var(--dg-mute); }

/* marble avatars: a sphere with a specular crescent */
[data-mari-part="avatar"] button,
[data-mari-part="avatar"] [data-mari-part="avatar-placeholder"]{
  position:relative;
  border-radius:50% !important;
  box-shadow:0 0 0 2px var(--dg-rim), 0 6px 14px -4px rgba(6,60,110,.55) !important;
}
[data-mari-part="avatar"] button::after{
  content:"";
  position:absolute; inset:0;
  border-radius:50%;
  background:
    radial-gradient(60% 38% at 50% 14%,rgba(255,255,255,.85),rgba(255,255,255,0) 70%),
    radial-gradient(70% 40% at 50% 100%,rgba(140,240,255,.45),transparent 70%);
  pointer-events:none;
}
[data-mari-part="avatar"] .rpg-avatar-glow{ box-shadow:none !important; filter:none !important; }

/* conversation: the same droplets, smaller, hung under each name */
[data-chat-mode="conversation"] [data-mari-part="message"] img,
[data-chat-mode="conversation"] [data-mari-part="avatar-placeholder"]{
  border-radius:50%;
  box-shadow:0 0 0 2px var(--dg-rim), 0 4px 10px -3px rgba(6,60,110,.5);
}
[data-mari-part="chat-header"] > *{
  border-radius:999px !important;
  background:var(--dg-gel-pill), var(--dg-glass) !important;
  border:1px solid var(--dg-rim) !important;
  box-shadow:var(--dg-shadow);
}

/* ═══ COMPOSER: a gel capsule docked to a glass orb ════════════════ */
[data-mari-part="composer"] .mari-chat-input-box{
  border-radius:999px !important;
  background:radial-gradient(farthest-side at 50% 0%,var(--dg-cap-hi) 0%,var(--dg-cap-mid) 55%,transparent 100%) 1.2rem 2px / calc(100% - 2.4rem) 52% no-repeat, var(--dg-glass) !important;
  border:1px solid var(--dg-rim) !important;
  box-shadow:var(--dg-shadow), inset 0 -2px 6px -2px var(--dg-caustic) !important;
  backdrop-filter:blur(16px) saturate(1.4);
  -webkit-backdrop-filter:blur(16px) saturate(1.4);
  padding-inline:.6rem .35rem !important;
}
[data-mari-part="composer"] textarea{ color:var(--dg-ink) !important; font-size:16px; }
[data-mari-part="composer"] textarea::placeholder{ color:var(--dg-faint) !important; opacity:1; }
[data-mari-part="composer"] .mari-chat-send-btn,
[data-mari-part="composer"] button[aria-label="Send"],
button[aria-label="Send game turn"]{
  width:2.75rem !important; height:2.75rem !important;
  border-radius:50% !important;
  background:url("theme:orb.webp") center / 100% 100% no-repeat !important;
  color:#fff !important;
  box-shadow:0 4px 10px -3px rgba(6,90,150,.6) !important;
  filter:none !important;
}
[data-mari-part="composer"] button[aria-label="Send"]:disabled{ opacity:.92; filter:saturate(.85) !important; }
[data-mari-part="composer"] .mari-chat-send-btn svg,
[data-mari-part="composer"] button[aria-label="Send"] svg,
button[aria-label="Send game turn"] svg{ filter:drop-shadow(0 1px 1px rgba(0,40,80,.6)); }
[data-mari-part="composer"] button:not(.mari-chat-send-btn):not([aria-label="Send"]){ border-radius:999px !important; color:var(--dg-mute); }

/* ═══ HOME: desktop gadgets ═════════════════════════════════════════ */
[data-mari-part="home-widget"]{
  background:var(--dg-gel), var(--dg-foot), var(--dg-glass) !important;
  box-shadow:var(--dg-shadow), inset 0 0 0 1px rgba(255,255,255,.25) !important;
  backdrop-filter:blur(16px) saturate(1.4);
  -webkit-backdrop-filter:blur(16px) saturate(1.4);
  --dg-cap:3.6rem;
}
[data-mari-part="home-widget-eyebrow"]{
  display:inline-block;
  width:max-content;
  padding:.15rem .7rem;
  border-radius:999px;
  background:var(--dg-aqua-gel);
  color:var(--dg-on-gel) !important;
  letter-spacing:.06em;
  font-weight:700;
}

/* ═══ DIALOGS, DRAWERS, WINDOWS: big droplets with an aurora cap ════ */
[role="dialog"][aria-modal="true"],
.mari-window,
.mari-drawer{
  border-radius:28px !important;
  border:1px solid var(--dg-rim) !important;
  background:
    url("theme:aurora-strip.webp") right 1.5rem top -3px / auto 14px no-repeat,
    linear-gradient(180deg,var(--dg-cap-hi) 0,var(--dg-cap-lo) 3.4rem,transparent 3.45rem),
    var(--dg-glass-deep) !important;
  box-shadow:0 24px 60px -20px rgba(4,40,80,.6), inset 0 0 0 1px rgba(255,255,255,.18) !important;
  backdrop-filter:blur(20px) saturate(1.4);
  -webkit-backdrop-filter:blur(20px) saturate(1.4);
  color:var(--dg-ink);
}

/* buttons everywhere: gel pills */
button[class*="bg-primary"],
.ov-btn--primary{
  border-radius:999px !important;
  background:var(--dg-aqua-gel) !important;
  color:var(--dg-on-gel) !important;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.5), 0 3px 8px -3px rgba(6,90,150,.6);
}

/* game: the narration box is a wide droplet over the lagoon */
[data-mari-part="message"][data-game-narration]{
  border-radius:var(--dg-drop) !important;
  background:var(--dg-gel), var(--dg-foot), var(--dg-glass) !important;
  border:1px solid var(--dg-rim) !important;
  box-shadow:var(--dg-shadow) !important;
  --dg-cap:3rem;
}
[data-mari-part="game-hud"]{
  border-radius:22px !important;
  background:var(--dg-gel), var(--dg-glass) !important;
  border:1px solid var(--dg-rim) !important;
}

/* conversation: every line is a small droplet (messenger-style), tip toward the marble */
[data-chat-mode="conversation"] [data-mari-part="message"] .mari-message-body{
  flex:0 1 auto;
  width:fit-content;
  max-width:min(46rem,100%);
  padding:.5rem 1.05rem .6rem;
  border-radius:var(--dg-tip) 22px 22px 22px;
  background:linear-gradient(180deg,var(--dg-cap-hi),var(--dg-cap-lo)) top / 100% 1.9rem no-repeat, var(--dg-foot), var(--dg-glass);
  border:1px solid var(--dg-rim);
  box-shadow:var(--dg-shadow);
  backdrop-filter:blur(12px) saturate(1.4);
  -webkit-backdrop-filter:blur(12px) saturate(1.4);
}
[data-chat-mode="conversation"] [data-mari-part="message"][data-message-role="user"] .mari-message-body{
  background:linear-gradient(180deg,var(--dg-cap-hi),var(--dg-cap-lo)) top / 100% 1.9rem no-repeat, var(--dg-foot), var(--dg-glass-user);
}
[data-chat-mode="conversation"] [data-mari-part="message"] .mari-message-name{ font-size:.98rem; }
[data-chat-mode="conversation"] [data-mari-part="message"]{ padding-block:.2rem; }
[data-chat-mode="conversation"] [data-mari-part="message"]:hover{ background:transparent !important; }

/* ═══ PAGES (Settings, Library, editors): one big droplet sheet ═══ */
.ov-settings,
.ov-gallery,
[data-component="OverhaulLibraryPage"]{
  margin:.7rem .7rem 0;
  border-radius:30px 30px 0 0;
  background:
    linear-gradient(180deg,var(--dg-cap-hi) 0,var(--dg-cap-lo) 6.5rem,transparent 6.55rem),
    var(--dg-glass) !important;
  border:1px solid var(--dg-rim);
  border-bottom:0;
  box-shadow:var(--dg-shadow);
  backdrop-filter:blur(18px) saturate(1.4);
  -webkit-backdrop-filter:blur(18px) saturate(1.4);
}
.ov-settings__head h1,
[data-mari-part="page-title"]{ font-family:var(--dg-round); font-weight:400; }
.ov-settings [role="tab"],
[data-component="OverhaulLibraryPage"] [role="tab"]{
  border-radius:999px !important;
  padding-inline:.55rem !important;
  border-bottom:0 !important;
}
.ov-settings [role="tab"].is-on,
.ov-settings [role="tab"][aria-selected="true"],
[data-component="OverhaulLibraryPage"] [role="tab"][aria-selected="true"]{
  background:var(--dg-aqua-gel) !important;
  color:var(--dg-on-gel) !important;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.55), 0 2px 6px -2px rgba(6,90,150,.5);
}
.ov-settings [role="tab"]::after,
.ov-settings [role="tab"]::before{ display:none !important; }
.ov-chip{ border-radius:999px !important; background:var(--dg-gel-pill), var(--dg-glass-deep) !important; border:1px solid var(--dg-rim) !important; }
.ov-settings__sections section{
  border-radius:22px !important;
  border-color:var(--dg-rim) !important;
  background:linear-gradient(180deg,var(--dg-cap-hi),var(--dg-cap-lo)) top / 100% 2.6rem no-repeat, var(--dg-glass-deep);
}
.ov-search{ border-radius:999px !important; }

/* Library sidebar nav: pills */
[data-component="OverhaulLibraryNav"] button,
[data-component="OverhaulLibraryNav"] a{ border-radius:999px !important; }

/* Library cards: glass tiles whose picture is a gel lens */
.ov-card__art{
  position:relative;
  border-radius:22px !important;
  overflow:hidden;
  box-shadow:0 0 0 1px var(--dg-rim), 0 10px 22px -10px rgba(6,60,110,.55) !important;
}
.ov-card__art::after{
  content:"";
  position:absolute; inset:0;
  background:linear-gradient(180deg,rgba(255,255,255,.55) 0%,rgba(255,255,255,.12) 38%,transparent 38.5%);
  border-radius:inherit;
  pointer-events:none;
}
.ov-gallery [class*="ov-seg"], .ov-gallery button{ border-radius:999px; }

/* phones: portrait art */
@media (max-width:1100px) and (orientation:portrait){
  :root[data-theme="light"]{ --mari-app-backdrop:url("theme:phone-day.webp"); }
  :root,:root[data-theme="dark"]{ --mari-app-backdrop:url("theme:phone-night.webp"); }
  :root{ --dg-drop:22px; --mari-ambient:none; --mari-app-backdrop-position:center top; }
}


/* name outside the droplet (phones, some layouts): a gel pill label */
[data-mari-part="message"] [data-mari-part="header"][data-placement="outside"]{
  width:fit-content;
  max-width:100%;
  padding:.15rem .85rem .2rem;
  margin-bottom:.3rem;
  border-radius:999px;
  background:var(--dg-gel-pill), var(--dg-glass) !important;
  border:1px solid var(--dg-rim);
  box-shadow:0 3px 8px -4px rgba(6,60,110,.45);
}

/* scene break: three rising bubbles instead of a rule */
[data-mari-part="message"] .mari-message-content hr{
  border:0 !important;
  height:12px;
  width:4.5rem;
  margin:1.1em auto;
  background:
    radial-gradient(circle at 50% 50%,var(--dg-aqua-hi) 0 2.5px,transparent 3px) 0 70% / 1.5rem 12px repeat-x,
    radial-gradient(circle at 50% 50%,rgba(255,255,255,.9) 0 1px,transparent 1.5px) .2rem 30% / 1.5rem 12px repeat-x;
  opacity:.9;
}

/* game portrait: a rounded glass lens */
[data-mari-part="message"][data-game-narration] [data-mari-part="avatar"],
[data-mari-part="message"][data-game-narration] [data-mari-part="avatar"] img{
  border-radius:20px !important;
}
[data-mari-part="message"][data-game-narration] [data-mari-part="avatar"]{
  box-shadow:0 0 0 2px var(--dg-rim), 0 8px 16px -6px rgba(6,60,110,.55);
  background-image:linear-gradient(180deg,rgba(255,255,255,.5),rgba(255,255,255,.1) 40%,transparent 40.5%);
}

/* Home hero: the mode chips and actions are gel pills on glass (they sit on bare sky) */
.ov-home-mode,
.ov-home-hero-actions .ov-btn{
  border-radius:999px !important;
  background:var(--dg-gel-pill), var(--dg-glass) !important;
  border:1px solid var(--dg-rim) !important;
  color:var(--dg-ink) !important;
  box-shadow:0 4px 12px -6px rgba(6,60,110,.55);
  backdrop-filter:blur(10px);
  -webkit-backdrop-filter:blur(10px);
}
.mari-home-hero h1,
[data-mari-part="home"] h1{ text-shadow:0 1px 0 rgba(255,255,255,.35), 0 2px 14px color-mix(in srgb,var(--dg-glass-solid) 70%,transparent); }

/* ═══ ROUND 2 ═══════════════════════════════════════════════════════ */

/* the droplet's tail: a small glass teardrop that hangs from the pinched corner toward the marble */
.mari-roleplay-message-body{ position:relative; }
.mari-rp-bubble{ position:relative; z-index:1; }
/* phones: no marble, so the name pill sits on the pinched corner and the tail goes */
@media (max-width:700px){
  [data-mari-part="message"] [data-mari-part="header"][data-placement="outside"]{
    z-index:2;
    margin-bottom:-.75rem !important;
    margin-top:.25rem;
    margin-inline:.4rem;
  }
  [data-mari-part="message"][data-message-role="user"] [data-mari-part="header"][data-placement="outside"]{ margin-left:auto; }
  [data-mari-part="message"] .mari-rp-bubble .px-4.py-3{ padding-top:1.1rem !important; }
}

/* conversation: you on the right, MSN-style */
[data-chat-mode="conversation"] [data-mari-part="message"][data-message-role="user"] [data-component="ConversationMessage.Content"]{
  flex-direction:row-reverse;
}
[data-chat-mode="conversation"] [data-mari-part="message"][data-message-role="user"] .mari-message-body{
  margin-left:auto;
  border-radius:22px var(--dg-tip) 22px 22px;
}
[data-chat-mode="conversation"] [data-mari-part="message"][data-message-role="user"] .mari-message-meta{ justify-content:flex-end; }
[data-chat-mode="conversation"] [data-mari-part="message"] .mari-message-body{ box-shadow:var(--dg-shadow), var(--dg-gel-rim); }
[data-chat-mode="conversation"] [data-mari-part="message"] .mari-message-body{
  background:var(--dg-gel), var(--dg-foot), var(--dg-glass);
  --dg-cap:2.1rem;
}
[data-chat-mode="conversation"] [data-mari-part="message"][data-message-role="user"] .mari-message-body{
  background:var(--dg-gel), var(--dg-foot), var(--dg-glass-user);
}

/* gel rim on every droplet surface */
[data-mari-part="home-widget"],
[data-mari-part="message"][data-game-narration],
.ov-settings, .ov-gallery,
[role="dialog"][aria-modal="true"], .mari-window, .mari-drawer{
  box-shadow:var(--dg-shadow), var(--dg-gel-rim) !important;
}
.ov-settings, .ov-gallery, [data-component="OverhaulLibraryPage"]{
  background:
    radial-gradient(farthest-side at 50% 0%,var(--dg-cap-hi) 0%,var(--dg-cap-mid) 50%,var(--dg-cap-lo) 82%,transparent 100%) 6px 2px / calc(100% - 12px) 6.5rem no-repeat,
    var(--dg-glass) !important;
}
[role="dialog"][aria-modal="true"], .mari-window, .mari-drawer{
  background:
    url("theme:aurora-strip.webp") right 1.5rem top -3px / auto 14px no-repeat,
    radial-gradient(farthest-side at 50% 0%,var(--dg-cap-hi) 0%,var(--dg-cap-mid) 50%,transparent 100%) 6px 2px / calc(100% - 12px) 3.4rem no-repeat,
    var(--dg-glass-deep) !important;
}

/* night sidebars: frost with an aurora tint at the top rim */
:root[data-theme="dark"] [data-component="ChatSidebar"],
:root[data-theme="dark"] [data-component="RightPanelDesktop"]{
  background:
    linear-gradient(180deg,rgba(80,230,255,.10),transparent 9rem),
    var(--dg-sidebar) !important;
}

/* Library rail: pill rows, the open page a lit gel pill */
.ov-libnav button{ border-radius:999px !important; }
.ov-libnav button.is-on,
.ov-libnav [aria-current="page"]{
  background:var(--dg-gel-pill), color-mix(in srgb,var(--dg-aqua) 22%,var(--dg-glass-solid)) !important;
  box-shadow:inset 0 0 0 1px var(--dg-rim), 0 3px 10px -4px rgba(6,90,150,.45);
}

/* native selects and inputs: gel capsules */
select{
  border-radius:999px !important;
  padding-inline:.9rem 2rem !important;
  background-color:var(--dg-glass-deep) !important;
  border:1px solid var(--dg-rim) !important;
  box-shadow:var(--dg-gel-rim);
  color:var(--dg-ink) !important;
}
.ov-settings__sections [class*="rounded-lg"][class*="border"],
.ov-settings__sections [class*="rounded-md"][class*="border"]{ border-radius:18px !important; }

/* Home: marbles and pills in the recent list; readable version tag */
[data-home-widget-id="recent"] [data-mari-part="avatar-placeholder"],
[data-home-widget-id="recent"] button img,
[data-home-widget-id="recent"] li img{
  border-radius:50% !important;
  box-shadow:0 0 0 2px var(--dg-rim), 0 4px 10px -3px rgba(6,60,110,.5);
}
[data-home-widget-id="recent"] span[class*="border"][class*="rounded"]{
  border-radius:999px !important;
  background:var(--dg-gel-pill), var(--dg-glass-deep);
  border-color:var(--dg-rim) !important;
}
[data-home-widget-id="recent"] [data-mari-part="home-widget-title"]{ margin-bottom:.45rem; }
.mari-home-hero [class*="tracking-[0.14em]"]{ color:var(--dg-ink) !important; opacity:.85; }

/* help overlay legends: droplets with the aurora rim */
[data-chat-help-action-legend],
[data-chat-help-settings-legend],
[data-chat-help-tools-legend]{
  border-radius:24px !important;
  border:1px solid var(--dg-rim) !important;
  background:
    url("theme:aurora-strip.webp") right 1.2rem top -3px / auto 12px no-repeat,
    radial-gradient(farthest-side at 50% 0%,var(--dg-cap-hi) 0%,var(--dg-cap-mid) 50%,transparent 100%) 6px 2px / calc(100% - 12px) 2.8rem no-repeat,
    var(--dg-glass-deep) !important;
  box-shadow:var(--dg-shadow), var(--dg-gel-rim) !important;
  backdrop-filter:blur(18px) saturate(1.4);
  -webkit-backdrop-filter:blur(18px) saturate(1.4);
  overflow:hidden;
}

/* scene break: three real glossy bubbles, rising */
[data-mari-part="message"] .mari-message-content hr{
  height:18px !important;
  width:5.2rem !important;
  background:
    radial-gradient(circle at 38% 32%,#fff 0 1.5px,transparent 2.5px) 0 100% / 1.75rem 18px repeat-x,
    radial-gradient(circle at 50% 50%,color-mix(in srgb,var(--dg-aqua-hi) 55%,transparent) 0 4px,var(--dg-aqua) 5px,transparent 6px) 0 100% / 1.75rem 18px repeat-x !important;
}

/* ═══ GAME: glass gadgets over the lagoon ═══════════════════════════ */
.ov-gpane{
  background:
    linear-gradient(180deg,rgba(255,255,255,.18),transparent 7rem),
    var(--dg-sidebar) !important;
  backdrop-filter:blur(18px) saturate(1.4);
  -webkit-backdrop-filter:blur(18px) saturate(1.4);
  box-shadow:inset 1px 0 0 var(--dg-rim);
}
.ov-gpane__table{ border-collapse:separate !important; border-spacing:0 .35rem !important; }
.ov-gpane__table thead th{ border:0 !important; }
.ov-gpane__table tbody tr{ background:transparent; }
.ov-gpane__table tbody td{
  border:0 !important;
  background:var(--dg-glass);
  border-block:1px solid var(--dg-rim) !important;
}
.ov-gpane__table tbody td:first-child{ border-radius:999px 0 0 999px; border-left:1px solid var(--dg-rim) !important; }
.ov-gpane__table tbody td:last-child{ border-radius:0 999px 999px 0; border-right:1px solid var(--dg-rim) !important; }
.ov-gpane__table img,
.ov-gpane__table [data-mari-part="avatar-placeholder"]{ border-radius:50% !important; box-shadow:0 0 0 2px var(--dg-rim); }
.ov-gpane button{ border-radius:999px !important; }
[data-tour="game-map"]{
  border-radius:22px !important;
  border:1px solid var(--dg-rim) !important;
  background:
    radial-gradient(farthest-side at 50% 0%,var(--dg-cap-hi) 0%,var(--dg-cap-mid) 50%,transparent 100%) 4px 2px / calc(100% - 8px) 2.2rem no-repeat,
    var(--dg-glass) !important;
  box-shadow:var(--dg-shadow), var(--dg-gel-rim) !important;
  backdrop-filter:blur(14px) saturate(1.4);
  -webkit-backdrop-filter:blur(14px) saturate(1.4);
}
[data-mari-part="game-tools"] button{ border-radius:999px !important; }
:root[data-theme="light"]{ --mari-game-combat-bg:#ffe1e6; --mari-game-combat-bg-hover:#ffd0d8; --mari-game-combat-border:#e0566c; --mari-game-combat-text:#9c1030; }
:root[data-theme="dark"]{ --mari-game-combat-bg:rgba(110,24,44,.7); --mari-game-combat-bg-hover:rgba(140,30,56,.8); --mari-game-combat-border:#ff7d93; --mari-game-combat-text:#ffd6dd; }
[data-composer="game"] .mari-chat-input-box,
[data-mari-part="composer"][data-composer="game"]{ border-radius:28px !important; }

/* weather art swaps, round 2: fog has its own misty twins */
:root[data-theme="light"][data-mari-weather="fog"]{ --mari-app-backdrop:url("theme:backdrop-fog.webp"); }
:root[data-theme="dark"][data-mari-weather="fog"]{ --mari-app-backdrop:url("theme:backdrop-fog-night.webp"); }
:root[data-mari-weather="snow"],:root[data-mari-weather="hail"]{ --mari-weather-amount:0.6; }
:root[data-mari-weather="storm"]{ --mari-weather-strength:1.5; --mari-weather-rain-length:2; }
[data-mari-part="message"] [data-mari-part="header"]{ border-bottom:0 !important; box-shadow:none !important; }

/* phones and tablets: the chat list sits on the portrait art, not on a blank frost */
:root[data-overhaul="mobile"][data-theme="light"] [data-component="ChatSidebar"]{
  background:linear-gradient(180deg,rgba(236,249,255,.62),rgba(236,249,255,.5) 60%,rgba(236,249,255,.2)), url("theme:phone-day.webp") center top / cover no-repeat !important;
}
:root[data-overhaul="mobile"][data-theme="dark"] [data-component="ChatSidebar"]{
  background:linear-gradient(180deg,rgba(4,26,46,.55),rgba(4,26,46,.45) 60%,rgba(4,26,46,.15)), url("theme:phone-night.webp") center top / cover no-repeat !important;
}
:root[data-overhaul="mobile"] [data-chat-row]{
  background:var(--dg-gel-pill), var(--dg-glass);
  border:1px solid var(--dg-rim);
  margin-block:.2rem;
}

/* ═══ ROUND 3 ═══════════════════════════════════════════════════════ */
/* one highlight per droplet: the name row carries no strip of its own */
[data-mari-part="message"] [data-mari-part="header"][data-placement="inside"],
.ov-rpmsg__head{ background:transparent !important; }
/* night chat sidebar: real frost with an aurora rim, like the Library rail */
:root[data-theme="dark"] [data-component="ChatSidebar"] > nav,
:root[data-theme="dark"] .mari-chat-sidebar{
  background:
    radial-gradient(120% 30% at 30% 0%,rgba(90,240,255,.20),transparent 70%),
    radial-gradient(90% 25% at 80% 100%,rgba(125,255,154,.10),transparent 70%),
    rgba(28,78,108,.42) !important;
  backdrop-filter:blur(22px) saturate(1.6) brightness(1.15) !important;
  -webkit-backdrop-filter:blur(22px) saturate(1.6) brightness(1.15) !important;
  box-shadow:inset -1px 0 0 rgba(190,246,255,.45), inset 0 1px 0 rgba(255,255,255,.25);
}

/* native select: capsule with an aqua chevron */
select:not([data-component="ChatSidebar"] select){
  appearance:none !important; -webkit-appearance:none !important;
  background-image:
    linear-gradient(45deg,transparent 50%,var(--dg-aqua) 50% 62%,transparent 62%),
    linear-gradient(-45deg,transparent 50%,var(--dg-aqua) 50% 62%,transparent 62%),
    radial-gradient(farthest-side at 50% 0%,var(--dg-cap-hi),transparent) !important;
  background-position:right 1.05rem center,right .7rem center,center top !important;
  background-size:.4rem .4rem,.4rem .4rem,calc(100% - 1rem) 50% !important;
  background-repeat:no-repeat !important;
}

/* game map: readable Generate */
[data-tour="game-map"] *{ color:var(--dg-ink) !important; }
[data-tour="game-map"] button{
  border-radius:999px !important; padding-inline:.7rem !important;
  background:var(--dg-aqua-gel) !important; color:var(--dg-on-gel) !important; font-weight:600;
}

/* Home recent: mode tags as gel pills */
.ov-recent__mode{
  border-radius:999px !important;
  background:var(--dg-gel-pill), var(--dg-glass-deep) !important;
  border:1px solid var(--dg-rim) !important;
  color:var(--dg-ink) !important;
  padding-inline:.6rem !important;
}

/* toasts: glass droplets */
[data-sonner-toast]{
  border-radius:22px !important;
  border:1px solid var(--dg-rim) !important;
  background:var(--dg-gel), var(--dg-glass-deep) !important;
  color:var(--dg-ink) !important;
  box-shadow:var(--dg-shadow), var(--dg-gel-rim) !important;
  backdrop-filter:blur(16px) saturate(1.4);
  -webkit-backdrop-filter:blur(16px) saturate(1.4);
  --dg-cap:2.2rem;
}

/* ═══ ROUND 4 ═══════════════════════════════════════════════════════ */
/* day droplets: crisp top highlight with a curved lower edge */
:root[data-theme="light"]{
  --dg-gel:radial-gradient(farthest-side at 50% 0%,rgba(255,255,255,1) 0%,rgba(255,255,255,.9) 62%,rgba(255,255,255,.55) 86%,rgba(255,255,255,0) 100%) 4px 2px / calc(100% - 8px) var(--dg-cap) no-repeat;
}
/* toast actions: aqua gel pill and a glass marble close */
[data-sonner-toast] button:not([data-close-button]),
[data-sonner-toast] [data-button]{
  border-radius:999px !important;
  background:var(--dg-aqua-gel) !important;
  color:var(--dg-on-gel) !important;
  border:1px solid var(--dg-rim) !important;
  box-shadow:0 2px 6px -2px rgba(6,90,150,.5) !important;
  font-weight:600;
}
[data-sonner-toast] [data-close-button]{
  border-radius:50% !important;
  background:radial-gradient(circle at 40% 30%,#fff 0 18%,transparent 45%), var(--dg-glass-deep) !important;
  color:var(--dg-ink) !important;
  border:1px solid var(--dg-rim) !important;
}
/* game party pane: caustic light and a bubble cluster at its foot */
.ov-gpane__body{
  background:
    url("theme:bubble-1.webp") right 2.2rem bottom 2.5rem / 64px 64px no-repeat,
    url("theme:bubble-1.webp") right 6.5rem bottom 5.5rem / 34px 34px no-repeat,
    url("theme:bubble-1.webp") right 4.4rem bottom 9rem / 22px 22px no-repeat,
    url("theme:bubble-1.webp") right 8.6rem bottom 1.8rem / 18px 18px no-repeat,
    radial-gradient(120% 40% at 50% 100%,var(--dg-caustic),transparent 70%) !important;
}

/* round 5: marble avatars on Home, a glint on the droplet tip, shorter phone shine */

.mari-rp-bubble::after{
  content:""; position:absolute; top:2px; left:5px;
  width:16px; height:5px; border-radius:50%;
  background:radial-gradient(closest-side,rgba(255,255,255,.95),rgba(255,255,255,0));
  transform:rotate(-38deg); pointer-events:none;
}
.mari-rp-bubble--user::after,
[data-mari-part="message"][data-message-role="user"] .mari-rp-bubble::after{ left:auto; right:5px; transform:rotate(38deg); }
@media (max-width:700px){ .mari-rp-bubble{ --dg-cap:1.15rem; } }
.ov-recent__avatar, .ov-recent__avatar img, .ov-recent__avatar [data-mari-part="avatar-placeholder"]{ border-radius:50% !important; overflow:hidden; }
.ov-recent__avatar{ box-shadow:0 0 0 2px var(--dg-rim), 0 4px 10px -3px rgba(6,60,110,.5); position:relative; }
button[aria-label="Send game turn"]{ width:2.5rem !important; height:2.5rem !important; }
[data-tour="game-map"] button, [data-tour="game-map"] button *{ color:var(--dg-on-gel) !important; }
[data-tour="game-map"] button svg{ stroke:var(--dg-on-gel) !important; }

/* the game's reply/prose box: smoked aqua glass, not a black well */
.game-narration-prose{
  border-radius:18px !important;
  border:1px solid var(--dg-rim) !important;
  background:radial-gradient(farthest-side at 50% 0%,var(--dg-cap-hi),transparent) 4px 1px / calc(100% - 8px) 1.6rem no-repeat, var(--dg-glass) !important;
  box-shadow:var(--dg-gel-rim);
}
/* first-run tutorial card: a big droplet with an aurora rim */
[data-component="OnboardingTutorial.Card"]{
  border-radius:28px !important;
  border:1px solid var(--dg-rim) !important;
  background:
    url("theme:aurora-strip.webp") right 1.5rem top -3px / auto 14px no-repeat,
    radial-gradient(farthest-side at 50% 0%,var(--dg-cap-hi) 0%,var(--dg-cap-mid) 50%,transparent 100%) 6px 2px / calc(100% - 12px) 5rem no-repeat,
    var(--dg-foot),
    var(--dg-glass-deep) !important;
  box-shadow:var(--dg-shadow), var(--dg-gel-rim) !important;
  backdrop-filter:blur(20px) saturate(1.4);
  -webkit-backdrop-filter:blur(20px) saturate(1.4);
}

/* ═══ ROUND 5 (1.1): one droplet sheet for every page, one right pane ═══ */
/* Every full page (Characters, Lorebooks, Presets, Regex, Connections, Agents, Custom tools,
   editors, Settings, Docs) sits in [data-mari-part="page"]: the droplet sheet lives there now,
   so Lorebooks gets the same glass as Characters. */
:root[data-theme] .mari-app [data-mari-part="page"][data-component][class]{
  border-radius:30px 30px 0 0;
  background:
    radial-gradient(farthest-side at 50% 0%,var(--dg-cap-hi) 0%,var(--dg-cap-mid) 50%,var(--dg-cap-lo) 82%,transparent 100%) 6px 2px / calc(100% - 12px) 6.5rem no-repeat,
    var(--dg-glass) !important;
  border:1px solid var(--dg-rim);
  border-bottom:0;
  box-shadow:var(--dg-shadow), var(--dg-gel-rim) !important;
  backdrop-filter:blur(18px) saturate(1.4);
  -webkit-backdrop-filter:blur(18px) saturate(1.4);
}
:root[data-theme] .mari-app [data-mari-part="page"][data-component="DetailEditor"]{ margin:.7rem .7rem 0; }
/* the old per-page sheets (still used on builds without the hook) step aside inside it: no double glass */
[data-mari-part="page"] :is(.ov-settings,.ov-gallery,[data-component="OverhaulLibraryPage"]){
  background:none !important;
  border:0 !important;
  box-shadow:none !important;
  backdrop-filter:none !important;
  -webkit-backdrop-filter:none !important;
  margin:0 !important;
  border-radius:0 !important;
}
/* day ink: the faintest grey-blue clears 4.5:1 on the glass */
:root[data-theme="light"]{ --dg-faint:#3d6178; }
/* night: section caps are a softer gleam so their descriptions stay crisp */
:root[data-theme="dark"] .ov-settings__sections section{
  background:linear-gradient(180deg,rgba(170,240,255,.14),rgba(170,240,255,.04)) top / 100% 2.6rem no-repeat, var(--dg-glass-deep);
}

/* ═══ THE ONE RIGHT PANE: frosted slab, Chats | Library as gel pills ═══ */
.ov-sideswitch{
  border-radius:999px !important;
  border:1px solid var(--dg-rim) !important;
  background:var(--dg-gel-pill), color-mix(in srgb,var(--dg-glass-solid) 55%,transparent);
  box-shadow:var(--dg-gel-rim), 0 4px 12px -6px rgba(6,60,110,.45);
  padding:.2rem;
}
.ov-sideswitch__btn{
  border-radius:999px !important;
  font-family:var(--dg-font);
  color:var(--dg-ink) !important;
}
.ov-sideswitch__btn.is-on{
  background:var(--dg-aqua-gel) !important;
  color:var(--dg-on-gel) !important;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.55), 0 2px 6px -1px rgba(6,90,150,.5);
}
/* inside the right pane the chat list is part of the slab (no second frost) */
.ov-sidepane [data-component="ChatSidebar"],
.ov-sidepane [data-component="ChatSidebar"] > nav,
.ov-sidepane .mari-chat-sidebar{
  background:transparent !important;
  backdrop-filter:none !important;
  -webkit-backdrop-filter:none !important;
  box-shadow:none !important;
}
:root[data-theme="dark"] [data-component="RightPanelDesktop"]:has(.ov-sidepane){
  background:
    radial-gradient(120% 22% at 30% 0%,rgba(90,240,255,.18),transparent 70%),
    radial-gradient(90% 20% at 80% 100%,rgba(125,255,154,.09),transparent 70%),
    var(--dg-sidebar) !important;
}

/* phones and tablets: the side page is a pane of frost over the portrait art */
:root[data-theme="light"] .ovm-sidepage{
  background:linear-gradient(180deg,rgba(236,249,255,.74),rgba(236,249,255,.62) 60%,rgba(236,249,255,.4)), url("theme:phone-day.webp") center top / cover no-repeat !important;
}
:root[data-theme="dark"] .ovm-sidepage{
  background:linear-gradient(180deg,rgba(4,26,46,.66),rgba(4,26,46,.56) 60%,rgba(4,26,46,.3)), url("theme:phone-night.webp") center top / cover no-repeat !important;
}
:root[data-overhaul][data-theme] .ovm-sidepage [data-component="ChatSidebar"]{ background:transparent !important; }
.ovm-sidepage .ovm-stack-menu__row{
  border-radius:999px !important;
  margin-block:.2rem;
  background:var(--dg-gel-pill), var(--dg-glass);
  border:1px solid var(--dg-rim);
  color:var(--dg-ink);
}
.ovm-sidepage__dock{ border-top-color:var(--dg-rim) !important; }
.ovm-sidepage .ovm-stack-menu__tile{
  border-radius:22px !important;
  background:var(--dg-gel-pill), var(--dg-glass);
  border:1px solid var(--dg-rim);
  color:var(--dg-ink);
  box-shadow:0 4px 12px -6px rgba(6,60,110,.45);
}
/* day: accent text (table heads, labels, "New" links) and mode tags in deeper inks so they read on glass */
:root[data-theme="light"]{
  --ov-accent:#055a8f;
  --ov-mode-conversation:#055a8f; --ov-mode-roleplay:#2a7210; --ov-mode-game:#7f4600;
}
/* night: the page sheet is a touch deeper smoked glass, so small muted text holds over bright aurora */
:root[data-theme="dark"]{ --dg-page-glass:rgba(7,40,64,.72); }
:root[data-theme="dark"] .mari-app [data-mari-part="page"][data-component][class]{
  background:
    radial-gradient(farthest-side at 50% 0%,var(--dg-cap-hi) 0%,var(--dg-cap-mid) 50%,var(--dg-cap-lo) 82%,transparent 100%) 6px 2px / calc(100% - 12px) 6.5rem no-repeat,
    var(--dg-page-glass) !important;
}
:root[data-theme="dark"]{ --ov-mode-game:#ffa938; }
/* phones and tablets: the page sheet floats over Home or a chat, so its glass is nearly solid */
:root[data-theme] .mari-app [data-mari-part="page"].mari-mobile-detail-sheet[data-component][class]{
  background:
    radial-gradient(farthest-side at 50% 0%,var(--dg-cap-hi) 0%,var(--dg-cap-mid) 50%,var(--dg-cap-lo) 82%,transparent 100%) 6px 2px / calc(100% - 12px) 6.5rem no-repeat,
    color-mix(in srgb,var(--dg-glass-solid) 94%,transparent) !important;
}
